PAYLOAD_SHA256 = "af5d9c013a2f02a221cb4902bf119a4c06d9caa87b200faafbf552fbf71ba051"


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def load_payload():
    data = zlib.decompress(base64.b85decode(PAYLOAD))
    if sha256(data) != PAYLOAD_SHA256:
        raise ValueError("O aplicador não passou na verificação de integridade.")
    package = json.loads(data)
    for item in package["files"]:
        relative = PurePosixPath(item["path"])
        if relative.is_absolute() or ".." in relative.parts or "\\" in item["path"]:
            raise ValueError("Caminho inválido no pacote.")
        data = base64.b64decode(item["content"], validate=True)
        if sha256(data) != item["new_sha256"]:
            raise ValueError("Conteúdo inválido: " + item["path"])
        if relative.suffix == ".py":
            ast.parse(data.decode("utf-8"), filename=item["path"])
        item["bytes"] = data
    return package


def safe_destination(root, relative):
    target = root / relative
    for part in (target, *target.parents):
        if part == root:
            break
        if part.is_symlink():
            raise ValueError("O caminho contém link simbólico: " + str(part))
    if not target.resolve().is_relative_to(root):
        raise ValueError("O destino fica fora da pasta do projeto.")
    return target


def write_atomic(path, data, mode=0o644):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix=".calculos-", dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(fd, "wb") as output:
            output.write(data)
            output.flush()
            os.fsync(output.fileno())
        temporary.chmod(mode)
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def normalized_sha256(data):
    # Accept only CRLF/LF and outer blank-line differences introduced by export.
    return sha256(data.replace(b"\r\n", b"\n").strip(b"\n") + b"\n")


def apply_update(root, package, dry_run=False):
    root = root.resolve()
    if not (root / "backend" / "app").is_dir() or not (root / "frontend" / "src").is_dir():
        raise ValueError("Escolha a pasta principal do projeto, que contém backend e frontend.")
    pending, conflicts = [], []
    for item in package["files"]:
        target = safe_destination(root, item["path"])
        if target.exists() and not target.is_file():
            conflicts.append(item["path"])
            continue
        current_bytes = target.read_bytes() if target.exists() else None
        current = sha256(current_bytes) if current_bytes is not None else None
        if current == item["new_sha256"]:
            continue
        matches_expected = current == item["old_sha256"]
        if not matches_expected and current_bytes is not None and item["old_sha256"] is not None:
            matches_expected = normalized_sha256(current_bytes) == item.get("old_normalized_sha256")
        if not matches_expected:
            conflicts.append(item["path"])
            continue
        pending.append((item, target, current))
    if conflicts:
        raise ValueError("Há arquivos diferentes da versão recebida. Nenhum arquivo foi alterado:\n" + "\n".join("  " + name for name in conflicts))
    if not pending:
        print("Correção já aplicada. Todos os arquivos conferem.")
        return None
    if dry_run:
        print(f"Verificação concluída: {len(pending)} arquivos prontos para atualização.")
        return None

    backup_root = safe_destination(root, "backups/correcao_calculos_moleculares")
    backup_root.mkdir(parents=True, exist_ok=True)
    backup = backup_root / datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    backup.mkdir()
    entries = []
    for item, target, actual_hash in pending:
        mode = stat.S_IMODE(target.stat().st_mode) if target.exists() else 0o644
        if target.exists():
            saved = backup / item["path"]
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, saved)
            if sha256(saved.read_bytes()) != actual_hash:
                raise ValueError("A cópia de segurança não confere: " + item["path"])
        entries.append({"path": item["path"], "old_sha256": actual_hash, "new_sha256": item["new_sha256"], "mode": mode})
    write_atomic(backup / "manifesto.json", json.dumps({"version": package["version"], "files": entries}, indent=2, ensure_ascii=False).encode("utf-8"))
    installed = []
    try:
        for (item, target, actual_hash), entry in zip(pending, entries):
            current = sha256(target.read_bytes()) if target.exists() else None
            if current != actual_hash:
                raise ValueError("Arquivo alterado durante a aplicação: " + item["path"])
            write_atomic(target, item["bytes"], entry["mode"])
            installed.append((item, target, entry["mode"], actual_hash))
            if sha256(target.read_bytes()) != item["new_sha256"]:
                raise ValueError("A gravação não confere: " + item["path"])
    except Exception as exc:
        failures = []
        for item, target, mode, actual_hash in reversed(installed):
            try:
                if sha256(target.read_bytes()) != item["new_sha256"]:
                    raise ValueError("Arquivo editado durante a restauração.")
                if actual_hash is None:
                    target.unlink()
                else:
                    write_atomic(target, (backup / item["path"]).read_bytes(), mode)
            except Exception:
                failures.append(item["path"])
        if failures:
            raise RuntimeError("Aplicação interrompida. Confira as cópias em " + str(backup) + ". Arquivos pendentes de restauração: " + ", ".join(failures)) from exc
        raise RuntimeError("Aplicação interrompida; arquivos substituídos foram restaurados. Cópias em " + str(backup)) from exc
    print(f"Correção aplicada: {len(installed)} arquivos atualizados.")
    print("Cópia dos arquivos anteriores: " + str(backup))
    print("Agora execute nesta pasta: bash iniciar_linux.sh")
    print("Depois, atualize a página com Ctrl+F5 e clique em Misturar.")
    print("Os testes estão em backend/tests e nos arquivos *.test.ts do frontend.")
    return backup


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--verificar", action="store_true", help="Conferir sem aplicar.")
    parser.add_argument("--projeto", type=Path, help="Pasta que contém backend e frontend.")
    args = parser.parse_args(argv)
    root = args.projeto
    if root is None:
        candidate = Path(__file__).resolve().parent
        root = candidate if (candidate / "backend" / "app").is_dir() else Path.cwd()
    try:
        apply_update(root, load_payload(), args.verificar)
        return 0
    except Exception as exc:
        print("Não foi possível aplicar a correção: " + str(exc), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
